6kw106kw-ip66-hybrid-solar-inverter-support-parallel', 1, 1, 1, 1, 1, 1, '24tr3', '["daffsd","fsdfsdfsdfsdf","Dual output for smart load control"]', 0, '["http://localhost:5000/uploads/1Kw-Ac-Solar-System-Package-1789242407384-218169699.jpg","http://localhost:5000/uploads/images__2_-1789242407473-650293058.jpg","http://localhost:5000/uploads/images__1_-1789242407613-288520914.jpg"]', 'http://localhost:5000/uploads/INVERTER_CATALOG-1789242565296-537913374.pdf', '[{"id":"spec-1789242623123-lgwfc","key":"MODEL","values":["XA6648","XA6648","XA6648"],"hasValues":true}]', '[{"id":"brochure-1789242653203","title":"dsadasd","pdfUrl":"http://localhost:5000/uploads/INVERTER_CATALOG-1789242665008-298775841.pdf","fileSize":"12.10 MB PDF"}]');
INSERT INTO `products` (`id`, `title`, `category`, `price`, `stock`, `status`, `description`, `image`, `created_at`, `updated_at`, `slug`, `sister_concern_id`, `product_category_id`, `product_sub_category_id`, `product_tree_category_id`, `product_brand_id`, `product_model_id`, `sku`, `features`, `is_featured`, `gallery_images`, `datasheet_pdf`, `datasheet_specs`, `brochures`) VALUES (1, 'fdsfjhsdf sfjdffsdfsd sdfjfkds', 'Solar Inverters', '435345.00', 1, 'published', '<p>frewrwefewfwe</p>', NULL, '2026-09-12 19:39:00', '2026-09-12 19:39:00', 'fdsfjhsdf-sfjdffsdfsd-sdfjfkds', 1, 1, 1, 1, 1, 1, '45435', '["ewrwrf","fsfdsfsdfdsf","fsdfsdfsdf","fsdfs","dffsdf"]', 0, NULL, NULL, NULL, NULL);
INSERT INTO `products` (`id`, `title`, `category`, `price`, `stock`, `status`, `description`, `image`, `created_at`, `updated_at`, `slug`, `sister_concern_id`, `product_category_id`, `product_sub_category_id`, `product_tree_category_id`, `product_brand_id`, `product_model_id`, `sku`, `features`, `is_featured`, `gallery_images`, `datasheet_pdf`, `datasheet_specs`, `brochures`) VALUES (1, 'Solvex XA10648 10.6kW Hybrid Solar Inverter with Dual MPPT', 'Solar Solutions', '2450.00', 1, 'published', '
<h3>On/Off-Grid Operation with Battery Power Export</h3>
<p>Dual on/off-grid modes support battery-free operation. Enables energy storage and grid feed-in under SUE/PEC modes, with dual AC inputs and automatic switching.</p>
<p>CT-based reverse current detection intelligently controls power flow, prioritizes self-use, prevents grid backfeed, and complies with energy regulations.</p>

<p class="ql-align-center"><img src="/assets/products/detail-1.jpg" alt="On/Off-Grid Inverter System" /></p>

<h3>LCD Capacitive Touch Screen Display</h3>
<p>Clear and intuitive interface with real-time display of current, voltage, power, energy data, and fault alarms for easy operation.</p>

<p class="ql-align-center"><img src="/assets/products/detail-2.jpg" alt="LCD Capacitive Display" /></p>

<h3>IP66 Protection for Harsh Outdoor Environments</h3>
<p>Dustproof and waterproof design protects against rain, wind, salt spray, humidity, and industrial cleaning, ensuring long-term stable operation.</p>

<p class="ql-align-center"><img src="/assets/products/detail-3.jpg" alt="IP66 Protection" /></p>

<h3>Parallel Expansion up to 9 Units</h3>
<p>Supports single-phase and three-phase parallel operation. Up to 9 units in single phase and up to 4 units per phase in three-phase systems.</p>

<p class="ql-align-center"><img src="/assets/products/detail-4.jpg" alt="Parallel Expansion" /></p>

<h3>Wide Application Compatibility</h3>
<p>Compatible with up to 99% of conventional electrical equipment. Flexible and practical for residential, commercial, and backup power applications.</p>

<p class="ql-align-center"><img src="/assets/products/detail-5.jpg" alt="Wide Applications" /></p>
