INSERT INTO `products` (`id`, `title`, `category`, `price`, `stock`, `status`, `description`, `image`, `created_at`, `updated_at`, `slug`, `sister_concern_id`, `product_category_id`, `product_sub_category_id`, `product_tree_category_id`, `product_brand_id`, `product_model_id`, `sku`, `features`, `is_featured`, `gallery_images`, `datasheet_pdf`, `datasheet_specs`, `brochures`) VALUES (1, 'Solvex MediClean 20kVA Isolated Hospital Grade Clean UPS', 'Solar Solutions', '7800.00', 1, 'published', '<h3 class="ql-align-center"><strong style="color: rgb(51, 51, 51);">On/Off-Grid&nbsp;Operation&nbsp;with&nbsp;Battery&nbsp;Power&nbsp;Export</strong></h3><ul><li><span style="color: rgb(85, 85, 85);">Dual&nbsp;on/off-grid&nbsp;modes&nbsp;support&nbsp;battery-free&nbsp;operation.&nbsp;Enables&nbsp;energy&nbsp;storage&nbsp;and&nbsp;grid&nbsp;feed-in&nbsp;under&nbsp;SUE/PEC&nbsp;modes,&nbsp;with&nbsp;dual&nbsp;AC&nbsp;inputs&nbsp;and&nbsp;automatic&nbsp;switching.</span></li><li><span style="color: rgb(85, 85, 85);">CT-based&nbsp;reverse&nbsp;current&nbsp;detection&nbsp;intelligently&nbsp;controls&nbsp;power&nbsp;flow,&nbsp;prioritizes&nbsp;self-use,&nbsp;prevents&nbsp;grid&nbsp;backfeed,&nbsp;and&nbsp;complies&nbsp;with&nbsp;energy&nbsp;regulations.</span></li></ul><p></p><p><span style="color: rgb(51, 51, 51);"><img src="https://ikrorwxhlkrmlo5p-static.micyjz.com/cloud/ljBpkKlploSRolrinijpiq/XA-SERIES-DETAIL.jpg" alt="XA-SERIES-DETAIL-2.jpg"></span></p><h3 class="ql-align-center"><strong style="color: rgb(51, 51, 51);">LCD&nbsp;Capacitive&nbsp;Touch&nbsp;Screen&nbsp;Display</strong></h3><ul><li><span style="color: rgb(85, 85, 85);">Clear&nbsp;and&nbsp;intuitive&nbsp;interface&nbsp;with&nbsp;real-time&nbsp;display&nbsp;of&nbsp;current,&nbsp;voltage,&nbsp;power,&nbsp;energy&nbsp;data,&nbsp;and&nbsp;fault&nbsp;alarms&nbsp;for&nbsp;easy&nbsp;operation.</span></li><li></li></ul><p><span style="color: rgb(51, 51, 51);"><img src="https://ikrorwxhlkrmlo5p-static.micyjz.com/cloud/lkBpkKlploSRolrinikpiq/XA-SERIES-DETAIL.jpg" alt="XA-SERIES-DETAIL-3.jpg"></span></p><h3 class="ql-align-center"><strong style="color: rgb(51, 51, 51);">IP66&nbsp;Protection&nbsp;for&nbsp;Harsh&nbsp;Outdoor&nbsp;Environments</strong></h3><ul><li><span style="color: rgb(85, 85, 85);">Dustproof&nbsp;and&nbsp;waterproof&nbsp;design&nbsp;protects&nbsp;against&nbsp;rain,&nbsp;wind,&nbsp;salt&nbsp;spray,&nbsp;humidity,&nbsp;and&nbsp;industrial&nbsp;cleaning,&nbsp;ensuring&nbsp;long-term&nbsp;stable&nbsp;operation.</span></li></ul><p></p><p><span style="color: rgb(51, 51, 51);"><img src="https://ikrorwxhlkrmlo5p-static.micyjz.com/cloud/llBpkKlploSRolrinilpiq/XA-SERIES-DETAIL.jpg" alt="XA-SERIES-DETAIL-4.jpg"></span></p><h3 class="ql-align-center"><strong style="color: rgb(51, 51, 51);">Parallel&nbsp;Expansion&nbsp;up&nbsp;to&nbsp;9&nbsp;Units</strong></h3><ul><li><span style="color: rgb(85, 85, 85);">Supports&nbsp;single-phase&nbsp;and&nbsp;three-phase&nbsp;parallel&nbsp;operation.&nbsp;Up&nbsp;to&nbsp;9&nbsp;units&nbsp;in&nbsp;single&nbsp;phase&nbsp;and&nbsp;up&nbsp;to&nbsp;4&nbsp;units&nbsp;per&nbsp;phase&nbsp;in&nbsp;three-phase&nbsp;systems.</span></li></ul><p></p><p><span style="color: rgb(51, 51, 51);"><img src="https://ikrorwxhlkrmlo5p-static.micyjz.com/cloud/lnBpkKlploSRolrininpiq/XA-SERIES-DETAIL.jpg" alt="XA-SERIES-DETAIL-5.jpg"></span></p><h3 class="ql-align-center"><strong style="color: rgb(51, 51, 51);">Wide&nbsp;Application&nbsp;Compatibility</strong></h3><ul><li><span style="color: rgb(85, 85, 85);">Compatible&nbsp;with&nbsp;up&nbsp;to&nbsp;99%&nbsp;of&nbsp;conventional&nbsp;electrical&nbsp;equipment.&nbsp;Flexible&nbsp;and&nbsp;practical&nbsp;for&nbsp;residential,&nbsp;commercial,&nbsp;and&nbsp;backup&nbsp;power&nbsp;applications.</span></li></ul><p></p><p></p><p></p>', 'https://images.unsplash.com/photo-1508873696983-2df57046475a?w=600', '2026-09-12 20:07:56', '2026-09-12 20:09:16', 'solvex-mediclean-20kva-isolated-hospital-grade-clean-ups', 1, 1, 1, 1, 1, 1, '202