"",""],"hasValues":false},{"id":"s35","key":"Parallel Function","values":["Yes, 9 units","Yes, 9 units","Yes, 9 units"],"hasValues":true},{"id":"s36","key":"Communication Port","values":["RS-232 / RS485, WIFI","RS-232 / RS485, WIFI","RS-232 / RS485, WIFI"],"hasValues":true},{"id":"s37","key":"ENVIRONMENT","values":["","",""],"hasValues":false},{"id":"s38","key":"Humidity","values":["0–100% RH (No condensing)","0–100% RH (No condensing)","0–100% RH (No condensing)"],"hasValues":true},{"id":"s39","key":"Operating Temperature","values":["-10°C to 50°C","-10°C to 50°C","-10°C to 50°C"],"hasValues":true},{"id":"s40","key":"PROTECTION & CERTIFICATE","values":["","",""],"hasValues":false},{"id":"s41","key":"Safety / EMC Standard","values":["IEC/EN 62109-1","IEC/EN 62109-2","IEC/EN 61000-6-2/4"],"hasValues":true}]', '[{"id":"b9","title":"Solvex MediClean 20kVA Hospital UPS Manual","pdfUrl":"http://localhost:5000/uploads/mediclean-20kva.pdf","fileSize":"4.7 MB PDF"}]');
INSERT INTO `products` (`id`, `title`, `category`, `price`, `stock`, `status`, `description`, `image`, `created_at`, `updated_at`, `slug`, `sister_concern_id`, `product_category_id`, `product_sub_category_id`, `product_tree_category_id`, `product_brand_id`, `product_model_id`, `sku`, `features`, `is_featured`, `gallery_images`, `datasheet_pdf`, `datasheet_specs`, `brochures`) VALUES (1, 'Solvex HyperCharge 120kW Dual-Gun DC Fast EV Charger', 'Solar Solutions', '8900.00', 1, 'published', '<h3 class="ql-align-center"><strong style="color: rgb(51, 51, 51);">On/Off-Grid&nbsp;Operation&nbsp;with&nbsp;Battery&nbsp;Power&nbsp;Export</strong></h3><ul><li><span style="color: rgb(85, 85, 85);">Dual&nbsp;on/off-grid&nbsp;modes&nbsp;support&nbsp;battery-free&nbsp;operation.&nbsp;Enables&nbsp;energy&nbsp;storage&nbsp;and&nbsp;grid&nbsp;feed-in&nbsp;under&nbsp;SUE/PEC&nbsp;modes,&nbsp;with&nbsp;dual&nbsp;AC&nbsp;inputs&nbsp;and&nbsp;automatic&nbsp;switching.</span></li><li><span style="color: rgb(85, 85, 85);">CT-based&nbsp;reverse&nbsp;current&nbsp;detection&nbsp;intelligently&nbsp;controls&nbsp;power&nbsp;flow,&nbsp;prioritizes&nbsp;self-use,&nbsp;prevents&nbsp;grid&nbsp;backfeed,&nbsp;and&nbsp;complies&nbsp;with&nbsp;energy&nbsp;regulations.</span></li></ul><p></p><p><span style="color: rgb(51, 51, 51);"><img src="https://ikrorwxhlkrmlo5p-static.micyjz.com/cloud/ljBpkKlploSRolrinijpiq/XA-SERIES-DETAIL.jpg" alt="XA-SERIES-DETAIL-2.jpg"></span></p><h3 class="ql-align-center"><strong style="color: rgb(51, 51, 51);">LCD&nbsp;Capacitive&nbsp;Touch&nbsp;Screen&nbsp;Display</strong></h3><ul><li><span style="color: rgb(85, 85, 85);">Clear&nbsp;and&nbsp;intuitive&nbsp;interface&nbsp;with&nbsp;real-time&nbsp;display&nbsp;of&nbsp;current,&nbsp;voltage,&nbsp;power,&nbsp;energy&nbsp;data,&nbsp;and&nbsp;fault&nbsp;alarms&nbsp;for&nbsp;easy&nbsp;operation.</span></li><li></li></ul><p><span style="color: rgb(51, 51, 51);"><img src="https://ikrorwxhlkrmlo5p-static.micyjz.com/cloud/lkBpkKlploSRolrinikpiq/XA-SERIES-DETAIL.jpg" alt="XA-SERIES-DETAIL-3.jpg"></span></p><h3 class="ql-align-center"><strong style="color: rgb(51, 51, 51);">IP66&nbsp;Protection&nbsp;for&nbsp;Harsh&nbsp;Outdoor&nbsp;Environments</strong></h3><ul><li><span style="color: rgb(85, 85, 85);">Dustproof&nbsp;and&nbsp;waterproof&nbsp;design&nbsp;protects&nbsp;against&nbsp;rain,&nbsp;wind,&nbsp;salt&nbsp;spray,&nbsp;humidity,&nbsp;and&nbsp;industrial&nbsp;cleaning,&nbsp;ensuring&nbsp;long-term&nbsp;stable&nbsp;operation.</span></li></ul><p></p><p><span style="color: rgb(51, 51, 51);"><img src="https://ikrorwxhlkrmlo5p-static.micyjz.com/cloud/llBpkKlploSRolrinilpiq/XA-SERIES-DETAIL.jpg" alt="XA-SERIES-DETAIL-4.jpg"></span></p><h3 class="ql-align-center"><strong style="color: rgb(51, 51, 51);">Parallel&nbsp;Expansion&nbsp;up&nbsp;to&nbsp;9&nbsp;Units</strong></h3><ul><li><span style="color: rgb(85, 85, 85);">Supports&nbsp;single-phase&nbsp;and&nbsp;three-phase&nbsp;parallel&nbsp;operation.&nbsp;Up&nbsp;to&nbsp;9&nbsp;units&nbsp;in&nbsp;single&nbsp;phase&nbsp;and&nbsp;up&nbsp;to&nbsp;4&nbsp;units&nbsp;per&nbsp;phase&nbsp;in&nbsp;three-phase&nbsp;systems.</span></li></ul><p></p><p><span style="color: rgb(51, 51, 51);"><img src="https://ikrorwxhlkrmlo5p-static.micyjz.com/cloud/lnBpkKlploSRolrininpiq/XA-SERIES-DETAIL.jpg" alt="XA-SERIES-DETAIL-5.jpg"></span></p><h3 class="ql-align-center"><strong style="color: rgb(51, 51, 51);">Wide&nbsp;Application&nbsp;Compatibility</strong></h3><ul><li><span style="color: rgb(85, 85, 85);">Compatible&nbsp;with&nbsp;up&nbsp;to&nbsp;99%&nbsp;of&nbsp;conventional&nbsp;electrical&nbsp;equipment.&nbsp;Flexible&nbsp;and&nbsp;practical&nbsp;for&nbsp;residential,&nbsp;commercial,&nbsp;and&nbsp;backup&nbsp;power&nbsp;applications.</span></li></ul><p></p><p></p><p></p>', 'https://images.unsplash.com/photo-1513836279014-a89f7a76ae86?w=600', '2026-09-12 20:07:56', '2026-09-12 20:32:35', 'solvex-hypercharge-120kw-dual-gun-dc-fast-ev-charger', 1, 1, 1, 1, 1, 1, '20260000000