INSERT INTO `projects` (`id`, `slug`, `project_category_id`, `label`, `big_title`, `description_cards`, `details_card`, `faq_icon`, `faq_title`, `faq_description`, `faq_questions`, `status`, `order_index`, `created_at`, `updated_at`) VALUES (1, '5-2-mwp-commercial-rooftop-solar-epc', 1, 'Turnkey Industrial EPC', '5.2 MWp Commercial Rooftop Solar EPC Deployment', '[{"title":"5.2 MWp","subtitle":"System Capacity"},{"title":"6.8 GWh","subtitle":"Annual Yield"},{"title":"4,200 Tons","subtitle":"CO2 Offset"},{"title":"3.8 Years","subtitle":"Capital Payback"}]', '[{"image":"http://localhost:5000/uploads/images__1_-1789238930833-499754276.jpg","label":"Milestone 01","title":"Structural Aerodynamic Modeling & Ballast Integration","image_left":false,"label_color":"#10B981","bullet_points":[{"text":"Zero roof penetration with marine-grade AL6005-T5 anodized aluminum clamping.","icon_color":"#10B981"},{"text":"Certified wind-tunnel resilience up to 180 km/h wind shear ratings.","icon_color":"#10B981"}],"description_1":"Engineered specifically for heavy industrial corrugated tin and standing seam roofs, featuring non-penetrating clamps tested to 180 km/h wind speeds.","description_2":"Full 3D LiDAR point-cloud scans and shadow analysis ensured maximum annual kilowatt-hour density across the 280,000 sq ft factory footprint."},{"image":"http://localhost:5000/uploads/images__2_-1789238943968-370086551.jpg","label":"Milestone 02","title":"Tier-1 TOPCon Bifacial Modules & String Inverter Architecture","image_left":true,"label_color":"#06B6D4","bullet_points":[{"text":"N-Type TOPCon bifacial modules achieving up to 22.8% conversion efficiency.","icon_color":"#06B6D4"},{"text":"Multi-MPPT string architecture with rapid shutdown and SCADA telemetry.","icon_color":"#06B6D4"}],"description_1":"Deployment of high-yield N-Type TOPCon bifacial modules coupled with multi-MPPT smart string inverters for real-time string-level yield optimization.","description_2":"Euro efficiency rating of 99.0% with automated AI-assisted arc fault circuit interruption (AFCI) protecting facility assets 24/7."}]', '', 'Project FAQs', 'Technical inquiries regarding the 5.2 MWp industrial rooftop project.', '[{"answer":"We deploy precision-engineered aluminum standing-seam clamps with EPDM rubber dampening that grip the seams without puncturing the roof sheet, preserving 100% of factory waterproofing warranties.","question":"How does the non-penetrating clamping protect the factory roof?"}]', 'published', 1, '2026-09-12 18:46:51', '2026-09-12 18:49:07');
