INSERT INTO `projects` (`id`, `slug`, `project_category_id`, `label`, `big_title`, `description_cards`, `details_card`, `faq_icon`, `faq_title`, `faq_description`, `faq_questions`, `status`, `order_index`, `created_at`, `updated_at`) VALUES (1, '3-6-mwp-pharma-cleanroom-solar', 1, 'Pharma Clean-Room', '3.6 MWp Pharmaceutical Manufacturing Clean Solar Array', '[{"title":"3.6 MWp","subtitle":"Peak Power"},{"title":"4.9 GWh","subtitle":"Annual Generation"},{"title":"Zero Dust","subtitle":"Sterile Standard"},{"title":"99.8%","subtitle":"Power Quality"}]', '[{"image":"https://images.unsplash.com/photo-1548337138-e87d889cc369?w=800&auto=format&fit=crop&q=80","label":"Milestone 01","title":"Cleanroom Safe Installation & Power Quality Harmonization","image_left":false,"label_color":"#10B981","bullet_points":[{"text":"Active harmonic filtering maintaining THD below 2.5%.","icon_color":"#10B981"},{"text":"Full WHO-GMP environmental compliance during execution.","icon_color":"#10B981"}],"description_1":"Engineered above sterile pharmaceutical formulation labs with active active harmonic filters ensuring clean power for precision lab instruments.","description_2":"Non-vibrational installation techniques ensured zero particulate contamination inside cleanrooms during mounting."}]', NULL, 'Pharma Solar FAQ', 'High-spec power quality and cleanroom safety.', '[{"answer":"No, our multi-level power conditioning and active filters provide cleaner sine-wave power than the incoming utility grid.","question":"Does solar power affect sensitive pharmaceutical machinery?"}]', 'published', 1, '2026-09-12 18:46:51', '2026-09-12 18:46:51');
INSERT INTO `projects` (`id`, `slug`, `project_category_id`, `label`, `big_title`, `description_cards`, `details_card`, `faq_icon`, `faq_title`, `faq_description`, `faq_questions`, `status`, `order_index`, `created_at`, `updated_at`) VALUES (1, '2-2-mwp-floating-solar-reservoir', 1, 'Water Reservoir FPV', '2.2 MWp Floating Solar PV Array on Industrial Reservoir', '[{"title":"2.2 MWp","subtitle":"Floating Solar"},{"title":"3.1 GWh","subtitle":"Annual Energy"},{"title":"35%","subtitle":"Evap Reduction"},{"title":"12%","subtitle":"Thermal Gain"}]', '[{"image":"https://images.unsplash.com/photo-1521618755572-156ae0cdd74d?w=800&auto=format&fit=crop&q=80","label":"Milestone 01","title":"Aquatic Pontoon Deployment on Raw Water Reservoir","image_left":false,"label_color":"#06B6D4","bullet_points":[{"text":"Conserved 18 million gallons of industrial water annually.","icon_color":"#06B6D4"},{"text":"Food-grade HDPE floats prevent water contamination.","icon_color":"#06B6D4"}],"description_1":"Built upon a textile factory\'s 12-acre raw water lake, conserving valuable expansion land while cooling the solar cells naturally.","description_2":"Anchored with corrosion-proof mooring cables accommodating a 5-meter seasonal water level variation."}]', NULL, 'Floating Solar FAQ', 'Aquatic stability and environmental benefits.', '[{"answer":"It actually improves water quality by shading the pond from UV sunlight, preventing algae blooms that clog treatment filters.","question":"Does floating solar affect water quality for factory processing?"}]', 'published', 1, '2026-09-12 18:46:51', '2026-09-12 18:46:51');
INSERT INTO `projects` (`id`, `slug`, `project_category_id`, `label`, `big_title`, `description_cards`, `details_card`, `faq_icon`, `faq_title`, `faq_description`, `faq_questions`, `status`, `order_index`, `created_at`, `updated_at`) VALUES (1, '4-5-mwp-steel-mill-solar-diesel-hybrid', 1, 'Steel Mill Microgrid', '4.5 MWp Steel Re-Rolling Mill Solar-Genset Microgrid', '[{"title":"4.5 MWp","subtitle":"PV Hybrid"},{"title":"1.8M Liters","subtitle":"Diesel Saved"},{"title":"Zero","subtitle":"Reverse Feed"},{"title":"100 ms","subtitle":"Response Speed"}]', '[{"image":"https://images.unsplash.com/photo-1473341304170-971dccb5ac1e?w=800&auto=format&fit=crop&q=80","label":"Milestone 01","title":"Heavy Inductive Load Management & Fast Solar Dispatch","image_left":false,"label_color":"#F59E0B","bullet_points":[{"text":"Advanced fast-response power curtailment prevents generator reverse-power trips.","icon_color":"#F59E0B"},{"text":"Real-time reactive power compensation boosts plant power factor.","icon_color":"#F59E0B"}],"description_1":"Steel mills experience severe load swings from electric arc furnaces and rolling stands. Our dynamic controller manages solar output in real-time.","description_2":"Synchronized with 4 x 2,000 kVA diesel generators to slash monthly fuel costs by over 40%."}]', NULL, 'Steel Mill Microgrid FAQ', 'Heavy industry power stabilization.', '[{"answer":"Yes, the hybrid controller works alongside generators and fast inverters to absorb voltage dips seamlessly.","question":"Can solar handle instantaneous motor starting surges?"}]', 'published', 1, '2026-09-12 18:46:51', '2026-09-12 18:46:51');
