INSERT INTO `projects` (`id`, `slug`, `project_category_id`, `label`, `big_title`, `description_cards`, `details_card`, `faq_icon`, `faq_title`, `faq_description`, `faq_questions`, `status`, `order_index`, `created_at`, `updated_at`) VALUES (1, '6-0-mwp-jute-packaging-solar', 1, 'Agro-Industrial Solar', '6.0 MWp Jute & Packaging Processing Facility Solar Array', '[{"title":"6.0 MWp","subtitle":"Total Output"},{"title":"8.1 GWh","subtitle":"Annual Yield"},{"title":"4,900 Tons","subtitle":"Emissions Avoided"},{"title":"4.1 Years","subtitle":"Payback Period"}]', '[{"image":"https://images.unsplash.com/photo-1559302504-64aae6ca6b6d?w=800&auto=format&fit=crop&q=80","label":"Milestone 01","title":"Long-Span Roof Structural Engineering for Agro-Industry","image_left":false,"label_color":"#10B981","bullet_points":[{"text":"High-yield N-Type TOPCon panels for humid sub-tropical conditions.","icon_color":"#10B981"},{"text":"Automated dry-cleaning system reduces water consumption to zero.","icon_color":"#10B981"}],"description_1":"Equipped with automated anti-soiling drone inspections and string-level fault monitoring across four large packaging mills.","description_2":"Generates massive operational cost savings that hedge the facility against rising grid utility tariffs."}]', NULL, 'Agro-Industrial Solar FAQ', 'Jute and packaging facility solar benefits.', '[{"answer":"Robotic dry-cleaning runs every morning before sunrise, keeping module glass spotless without manual water spraying.","question":"How does the system handle fiber dust accumulation?"}]', 'published', 1, '2026-09-12 18:46:51', '2026-09-12 18:46:51');
INSERT INTO `projects` (`id`, `slug`, `project_category_id`, `label`, `big_title`, `description_cards`, `details_card`, `faq_icon`, `faq_title`, `faq_description`, `faq_questions`, `status`, `order_index`, `created_at`, `updated_at`) VALUES (1, '15-mwp-cement-clinker-renewable-station', 1, 'Heavy Industry Microgrid', '15 MWp Cement Clinker Facility Renewable Power Station', '[{"title":"15.0 MWp","subtitle":"PV System"},{"title":"21.6 GWh","subtitle":"Clean Energy"},{"title":"14,200 Tons","subtitle":"CO2 Cut"},{"title":"33kV","subtitle":"Dedicated Feeder"}]', '[{"image":"https://images.unsplash.com/photo-1466611653911-95081537e5b7?w=800&auto=format&fit=crop&q=80","label":"Milestone 01","title":"High-Voltage Interconnection & Heavy Industrial Offset","image_left":false,"label_color":"#F59E0B","bullet_points":[{"text":"High-spec IP66 inverters engineered for dusty cement environments.","icon_color":"#F59E0B"},{"text":"Full SCADA remote telemetry dispatch integrated with plant DCS.","icon_color":"#F59E0B"}],"description_1":"Supplying green energy directly to high-torque ball mills and clinker crushers via a dedicated 33kV internal substation.","description_2":"Significantly reduces the carbon intensity of cement manufacturing to comply with green building standards."}]', NULL, 'Cement Industry Solar FAQ', 'High-dust heavy industrial clean energy.', '[{"answer":"All inverters and junction boxes feature IP66 hermetic sealing with pressurized cooling channels to prevent abrasive dust ingress.","question":"How does the electrical equipment handle heavy cement dust?"}]', 'published', 1, '2026-09-12 18:46:51', '2026-09-12 18:46:51');

