INSERT INTO `services` (`id`, `slug`, `title`, `short_description`, `tags`, `hero_image`, `cards`, `hardware_card`, `consultation_card`, `faqs`, `status`, `order_index`, `created_at`, `updated_at`) VALUES (1, 'ci-turnkey-solar-pv-systems', 'C&I Turnkey Solar PV Systems', 'Comprehensive EPC solutions designed for factories, textile mills, warehouses, and commercial establishments. Engineered for high yield, structural integrity, and maximum net-metering benefits.', '["COMMERCIAL & INDUSTRIAL SOLAR","TURNKEY EPC"]', 'https://images.unsplash.com/photo-1508873696983-2df5293cb395?w=1200&auto=format&fit=crop&q=80', '[{"id":"card-1","image":"https://images.unsplash.com/photo-1508873696983-2df5293cb395?w=800&auto=format&fit=crop&q=80","title":"Structural Engineering & Aerodynamic Design","phase_tag":"PHASE 01 SYSTEM ARCHITECTURE","image_left":false,"description":"Engineered for maximum resilience and high yield in heavy industrial environments.","bullet_points":["Custom ballast and non-penetrating aluminum mounting for tin, RCC, and standing-seam roofs designed to withstand 180 km/h wind speeds.","Full 3D shadow analysis and thermal modeling to ensure peak kilowatt-hour generation year-round."]},{"id":"card-2","image":"https://images.unsplash.com/photo-1509391365360-2e959784a276?w=800&auto=format&fit=crop&q=80","title":"Tier-1 High-Efficiency Bifacial Modules","phase_tag":"PHASE 02 SYSTEM ARCHITECTURE","image_left":true,"description":"State-of-the-art TOPCon and heterojunction cell technology delivering ultra-low degradation.","bullet_points":["Deployment of N-Type TOPCon and heterojunction bifacial panels with up to 23.5% module efficiency and 30-year linear performance warranty.","Integrated with smart multi-MPPT string inverters providing up to 99.0% Euro efficiency and AFCI arc-fault protection."]}]', '{"title":"Industrial Solar PV Package","card_color":"#0F172A","button_text":"VIEW TECHNICAL SPECIFICATIONS","description":"Tier-1 TOPCon Bifacial Panels, High-Efficiency Multi-MPPT String Inverters, and Weather-Proof SCADA Combiner Boxes.","button_color":"#10B981"}', '{"title":"Request Rooftop Feasibility Study","card_color":"#047857","button_text":"BOOK FREE SITE AUDIT","description":"Our certified design engineers provide complimentary structural shadow analysis and electrical load auditing free of charge.","button_color":"#F59E0B"}', '[{"answer":"With modern 580W-700W N-Type TOPCon modules, approximately 60,000 to 75,000 square feet of unobstructed roof space is required per 1 MWp installation.","question":"How much factory roof space is required per megawatt (1 MWp)?"},{"answer":"In most industrial manufacturing facilities, net-metered rooftop solar achieves full capital payback within 3.5 to 5 years against volatile national grid tariffs.","question":"What is the typical payback period for a commercial solar project?"}]', 'published', 1, '2026-09-12 18:46:51', '2026-09-12 18:46:51');
INSERT INTO `services` (`id`, `slug`, `title`, `short_description`, `tags`, `hero_image`, `cards`, `hardware_card`, `consultation_card`, `faqs`, `status`, `order_index`, `created_at`, `updated_at`) VALUES (1, 'commercial-industrial-bess-storage', 'Battery Energy Storage Systems (BESS)', 'Utility-scale and commercial containerized Lithium-Iron-Phosphate (LFP) battery energy storage designed for peak shaving, diesel fuel displacement, and zero-interruption UPS power backup.', '["ENERGY STORAGE","MICROGRID & BESS"]', 'https://images.unsplash.com/photo-1513836279014-a89f7a76ae86?w=1200&auto=format&fit=crop&q=80', '[{"id":"card-1","image":"https://images.unsplash.com/photo-1513836279014-a89f7a76ae86?w=800&auto=format&fit=crop&q=80","title":"Containerized Tier-1 LFP Battery Architecture","phase_tag":"PHASE 01 STORAGE INTEGRATION","image_left":false,"description":"Modular, liquid-cooled lithium iron phosphate battery racks with automated aerosol fire suppression.","bullet_points":["Over 6,000 deep discharge cycles at 90% Depth of Discharge with a 10-to-15 year operating design lifespan.","Integrated Liquid Cooling thermal management guaranteeing cell-to-cell delta temperature under 2.5°C."]},{"id":"card-2","image":"https://images.unsplash.com/photo-1548337138-e87d889cc369?w=800&auto=format&fit=crop&q=80","title":"Intelligent Hybrid PCS & Microgrid Controller","phase_tag":"PHASE 02 ENERGY MANAGEMENT","image_left":true,"description":"Sub-millisecond islanding transfer switch ensuring critical production loads never see a blackout.","bullet_points":["Sub-20ms seamless grid-to-island transition displacing costly diesel generator spinning reserves.","Smart AI time-of-use energy arbitrage charging during off-peak hours and discharging during peak tariff bands."]}]', '{"title":"Modular 1MWh - 10MWh BESS Container","card_color":"#0F172A","button_text":"REQUEST BESS SPECSHEET","description":"Liquid-cooled LFP battery packs, bi-directional PCS inverters, and IP55 outdoor enclosures.","button_color":"#06B6D4"}', '{"title":"Simulate Peak-Shaving ROI","card_color":"#0E7490","button_text":"SCHEDULE BESS AUDIT","description":"Upload your utility interval load profile for an instant financial model on diesel replacement and peak tariff reductions.","button_color":"#10B981"}', '[{"answer":"Yes, when paired with solar PV and microgrid control, BESS provides immediate zero-emission backup and eliminates diesel fuel, oil maintenance, and generator startup delays.","question":"Can BESS replace industrial diesel generators entirely?"},{"answer":"Our systems feature multi-tier BMS monitoring, NFPA 855 compliant deflagration venting, gas detection, and automated aerosol clean-agent fire suppression.","question":"What safety protocols are engineered into your battery containers?"}]', 'published', 1, '2026-09-12 18:46:51', '2026-09-12 18:46:51');
INSERT INTO `services` (`id`, `slug`, `title`, `short_description`, `tags`, `hero_image`, `cards`, `hardware_card`, `consultation_card`, `faqs`, `status`, `order_index`, `created_at`, `updated_at`) VALUES (1, 'hybrid-microgrid-generator-sync', 'Solar-Diesel Microgrid Synchronization', 'Intelligent fuel-saver controllers enabling solar arrays to synchronize directly with on-site diesel and gas generators with zero reverse-power risk.', '["MICROGRID AUTOMATION","HYBRID CONTROLLERS"]', 'https://images.unsplash.com/photo-1473341304170-971dccb5ac1e?w=1200&auto=format&fit=crop&q=80', '[{"id":"card-1","image":"https://images.unsplash.com/photo-1473341304170-971dccb5ac1e?w=800&auto=format&fit=crop&q=80","title":"Zero Reverse-Power & Dynamic Fuel Saver","phase_tag":"PHASE 01 SYNCHRONIZATION","image_left":false,"description":"High-speed programmable microgrid controllers orchestrating solar and genset dispatch.","bullet_points":["Maintains minimum 30% generator loading to prevent engine wet-stacking and thermal damage.","Sub-second solar throttling prevents reverse power flow when heavy factory machinery turns off."]}]', '{"title":"Hybrid Controller & Metering Panel","card_color":"#0F172A","button_text":"EXPLORE FUEL SAVER TECH","description":"Woodward/DEIF fuel-saver controller, Class 0.2s power transducers, and high-speed fiber-optic bus.","button_color":"#10B981"}', '{"title":"Calculate Fuel Savings","card_color":"#047857","button_text":"CALCULATE GENSET SAVINGS","description":"Find out how much diesel and natural gas your factory can save every month with integrated solar hybrid sync.","button_color":"#F59E0B"}', '[{"answer":"No. Our automated fuel-saver controller reacts within 100 milliseconds to curtail solar if load drops, ensuring zero reverse power into generator alternators.","question":"Will solar back-feed power into our generators?"}]', 'published', 1, '2026-09-12 18:46:51', '2026-09-12 18:46:51');
INSERT INTO `services` (`id`, `slug`, `title`, `short_description`, `tags`, `hero_image`, `cards`, `hardware_card`, `consultation_card`, `faqs`, `status`, `order_index`, `created_at`, `updated_at`) VALUES (1, 'utility-scale-ground-mounted-solar', 'Utility-Scale Ground-Mounted Solar Farms', 'Gigawatt-scale ground-mounted solar power plants featuring single-axis AI astronomical trackers, high-voltage 33kV/132kV substations, and grid interconnection.', '["UTILITY SOLAR","GROUND MOUNTED"]', 'https://images.unsplash.com/photo-1497435334941-8c899ee9e8e9?w=1200&auto=format&fit=crop&q=80', '[{"id":"card-1","image":"https://images.unsplash.com/photo-1497435334941-8c899ee9e8e9?w=800&auto=format&fit=crop&q=80","title":"AI Single-Axis Astronomical Trackers","phase_tag":"PHASE 01 FIELD ENGINEERING","image_left":false,"description":"High-yield tracking structures increasing annual energy generation by 18% to 25% over fixed-tilt systems.","bullet_points":["Smart backtracking algorithms prevent inter-row shading on rolling terrain and uneven topography.","Certified wind stow defensive mode triggering automatic 0° aerodynamic protection during severe cyclones."]}]', '{"title":"Utility Power Plant Balance of System","card_color":"#0F172A","button_text":"UTILITY SPECIFICATIONS","description":"Single-axis trackers, 3.125MW central inverter skid stations, and oil-immersed step-up transformers.","button_color":"#10B981"}', '{"title":"Land Feasibility & PPA Advisory","card_color":"#047857","button_text":"CONSULT WITH UTILITY TEAM","description":"We provide comprehensive land geotechnical assessment, grid interconnection feasibility, and tariff structuring.","button_color":"#F59E0B"}', '[{"answer":"With modern single-axis trackers and 700W+ bifacial modules, a 10 MWp project requires approximately 30 to 35 acres of land.","question":"How much land is required for a 10 MWp solar farm?"}]', 'published', 1, '2026-09-12 18:46:51', '2026-09-12 18:46:51');
INSERT INTO `services` (`id`, `slug`, `title`, `short_description`, `tags`, `hero_image`, `cards`, `hardware_card`, `consultation_card`, `faqs`, `status`, `order_index`, `created_at`, `updated_at`) VALUES (1, 'net-metering-and-grid-synchronization', 'Net Metering & Regulatory Liaison', 'End-to-end regulatory approvals, utility substation compliance, bidirectional smart meter installation, and commercial tariff credit optimization.', '["NET METERING","UTILITY LIAISON"]', 'https://images.unsplash.com/photo-1613665813446-82a78c468a1d?w=1200&auto=format&fit=crop&q=80', '[{"id":"card-1","image":"https://images.unsplash.com/photo-1613665813446-82a78c468a1d?w=800&auto=format&fit=crop&q=80","title":"Grid Interconnection & Smart Bidirectional Metering","phase_tag":"PHASE 01 REGULATORY APPROVALS","image_left":false,"description":"Complete utility liaison with power authorities ensuring frictionless net-metering synchronization.","bullet_points":["Class 0.2s accuracy smart net meter deployment with optical telemetry for real-time power export verification.","Full compliance with National Grid code harmonics, anti-islanding, and power factor regulations."]}]', '{"title":"Utility-Approved Net Metering Skid","card_color":"#0F172A","button_text":"VIEW COMPLIANCE HARDWARE","description":"Bidirectional 4-quadrant energy meters, CT/PT metering cabinets, and vacuum circuit breakers.","button_color":"#10B981"}', '{"title":"Net Metering Eligibility Check","card_color":"#047857","button_text":"CHECK ELIGIBILITY","description":"Our regulatory team evaluates your sanctioned load, substation capacity, and utility zone rules.","button_color":"#F59E0B"}', '[{"answer":"Depending on your sanctioned load and roof area, up to 100% of daytime energy consumption and export credits can be offset against your utility bill.","question":"What percentage of electricity bill can be offset through net metering?"}]', 'published', 1, '2026-09-12 18:46:51', '2026-09-12 18:46:51');
INSERT INTO `services` (`id`, `slug`, `title`, `short_description`, `tags`, `hero_image`, `cards`, `hardware_card`, `consultation_card`, `faqs`, `status`, `order_index`, `created_at`, `updated_at`) VALUES (1, 'scada-iot-remote-monitoring', 'Smart SCADA & AI Remote Telemetry', '24/7 cloud SCADA analytics, string-level electrical monitoring, digital weather stations, and automated machine-learning performance ratio (PR) tracking.', '["AI SCADA","DIGITAL ASSET MANAGEMENT"]', 'https://images.unsplash.com/photo-1581092160607-ee22621dd758?w=1200&auto=format&fit=crop&q=80', '[{"id":"card-1","image":"https://images.unsplash.com/photo-1581092160607-ee22621dd758?w=800&auto=format&fit=crop&q=80","title":"Real-Time Inverter & String Analytics","phase_tag":"PHASE 01 TELEMETRY","image_left":false,"description":"Continuous telemetry monitoring capturing 1-second interval electrical and meteorological parameters.","bullet_points":["Automated detection of soiling losses, cracked diodes, string shading, and inverter clipping.","Integrated IEC 61724-1 Class-A weather stations measuring GHI, POA irradiance, ambient temp, and wind velocity."]}]', '{"title":"Industrial IoT SCADA Gateways","card_color":"#0F172A","button_text":"EXPLORE SCADA DASHBOARD","description":"Cellular 4G/5G edge gateways, Modbus RTU/TCP data loggers, and pyranometers.","button_color":"#10B981"}', '{"title":"Demo Live Solar Plant Telemetry","card_color":"#047857","button_text":"BOOK A LIVE DEMO","description":"Experience our live production monitoring dashboard and real-time fault alert dispatch system.","button_color":"#F59E0B"}', '[{"answer":"No, edge IoT gateways securely transmit encrypted data to our ISO 27001 certified cloud platform, accessible via mobile app and web browser.","question":"Does the monitoring system require a dedicated on-site server?"}]', 'published', 1, '2026-09-12 18:46:51', '2026-09-12 18:46:51');
INSERT INTO `services` (`id`, `slug`, `title`, `short_description`, `tags`, `hero_image`, `cards`, `hardware_card`, `consultation_card`, `faqs`, `status`, `order_index`, `created_at`, `updated_at`) VALUES (1, 'solar-operations-and-maintenance-om', 'Comprehensive Solar Operations & Maintenance', 'Preventive O&M services, robotic dry module cleaning, thermographic drone infrared inspections, and guaranteed 99% uptime availability SLAs.', '["OPERATIONS & MAINTENANCE","ASSET MANAGEMENT"]', 'https://images.unsplash.com/photo-1559302504-64aae6ca6b6d?w=1200&auto=format&fit=crop&q=80', '[{"id":"card-1","image":"https://images.unsplash.com/photo-1559302504-64aae6ca6b6d?w=800&auto=format&fit=crop&q=80","title":"Robotic Cleaning & Thermographic Drone Scans","phase_tag":"PHASE 01 ASSET RELIABILITY","image_left":false,"description":"Preventing hotspot cell degradation and ensuring consistent peak solar conversion.","bullet_points":["Thermal drone scans compliant with IEC 62446-3 identifying micro-cracks and bypass diode failures.","Waterless autonomous robotic module cleaning avoiding roof water accumulation and module surface scratching."]}]', '{"title":"Preventive O&M Contract Packages","card_color":"#0F172A","button_text":"VIEW O&M PACKAGES","description":"Scheduled preventive servicing, rapid 2-hour response dispatch, and spare parts warehousing.","button_color":"#10B981"}', '{"title":"Request Plant Health Checkup","card_color":"#047857","button_text":"SCHEDULE HEALTH CHECK","description":"Our certified technicians conduct comprehensive IV-curve tracing and thermal inspection of your existing solar plant.","button_color":"#F59E0B"}', '[{"answer":"In typical industrial textile and manufacturing corridors, bi-weekly or monthly automated cleaning recovers 8% to 15% of lost power generation.","question":"How often should industrial solar panels be cleaned?"}]', 'published', 1, '2026-09-12 18:46:51', '2026-09-12 18:46:51');
INSERT INTO `services` (`id`, `slug`, `title`, `short_description`, `tags`, `hero_image`, `cards`, `hardware_card`, `consultation_card`, `faqs`, `status`, `order_index`, `created_at`, `updated_at`) VALUES (1, 'floating-solar-pv-systems', 'Floating Solar PV (FPV) Systems', 'Pioneering floating solar arrays engineered for water reservoirs, raw water retention ponds, and industrial effluent treatment ponds.', '["FLOATING SOLAR","WATER RESERVOIR"]', 'https://images.unsplash.com/photo-1521618755572-156ae0cdd74d?w=1200&auto=format&fit=crop&q=80', '[{"id":"card-1","image":"https://images.unsplash.com/photo-1521618755572-156ae0cdd74d?w=800&auto=format&fit=crop&q=80","title":"Food-Grade HDPE Modular Floats & Mooring","phase_tag":"PHASE 01 AQUATIC ENGINEERING","image_left":false,"description":"Maximizing unused water bodies without consuming valuable commercial land.","bullet_points":["Water natural cooling effect boosts module electrical conversion efficiency by up to 12.5%.","Significantly reduces reservoir water evaporation by up to 35% while suppressing harmful algae blooms."]}]', '{"title":"Floating Solar Pontoon Architecture","card_color":"#0F172A","button_text":"FPV TECHNICAL DETAILS","description":"UV-stabilized HDPE pontoons, corrosion-resistant anchoring cables, and submerged cables.","button_color":"#10B981"}', '{"title":"Water Reservoir Feasibility","card_color":"#047857","button_text":"BOOK RESERVOIR AUDIT","description":"Assess bathymetry, water level fluctuations, and wind wave dynamics for floating solar deployment.","button_color":"#F59E0B"}', '[{"answer":"Yes, our tensioned elastic anchoring systems automatically adjust for seasonal water depth variations and withstand up to 160 km/h wind shear.","question":"Can floating solar withstand severe wave action and monsoons?"}]', 'published', 1, '2026-09-12 18:46:51', '2026-09-12 18:46:51');
INSERT INTO `services` (`id`, `slug`, `title`, `short_description`, `tags`, `hero_image`, `cards`, `hardware_card`, `consultation_card`, `faqs`, `status`, `order_index`, `created_at`, `updated_at`) VALUES (1, 'solar-carports-and-ev-charging', 'Solar Carports & EV Fleet Charging Hubs', 'Architectural steel canopy structures providing shaded parking for employee and executive fleets while charging electric vehicles with clean solar energy.', '["SOLAR CARPORTS","EV MOBILITY"]', 'https://images.unsplash.com/photo-1545209568-98e3b3318182?w=1200&auto=format&fit=crop&q=80', '[{"id":"card-1","image":"https://images.unsplash.com/photo-1545209568-98e3b3318182?w=800&auto=format&fit=crop&q=80","title":"Architectural Waterproof Solar Canopies","phase_tag":"PHASE 01 STRUCTURAL CANOPY","image_left":false,"description":"Dual-purpose engineering that monetizes corporate parking space into revenue-generating solar hubs.","bullet_points":["Heavy-duty galvanized structural steel frames with integrated rainwater gutters and drainage.","Integrated Level-2 AC and 60kW-180kW DC Ultra-Fast EV chargers for corporate fleet charging."]}]', '{"title":"Canopy Steel & Fast-Charger Package","card_color":"#0F172A","button_text":"VIEW CARPORT SPECS","description":"Hot-dip galvanized structural framing, bifacial solar glass, and OCPP-compliant EV chargers.","button_color":"#10B981"}', '{"title":"Parking Lot Solar Design","card_color":"#047857","button_text":"REQUEST CARPORT PROPOSAL","description":"Send us your parking lot layout for an instant 3D layout rendering, vehicle capacity analysis, and generation model.","button_color":"#F59E0B"}', '[{"answer":"Yes, our carport systems feature patented EPDM rubber compression seals and hidden internal gutter channels for 100% dry parking underneath.","question":"Are solar carports completely waterproof?"}]', 'published', 1, '2026-09-12 18:46:51', '2026-09-12 18:46:51');
INSERT INTO `services` (`id`, `slug`, `title`, `short_description`, `tags`, `hero_image`, `cards`, `hardware_card`, `consultation_card`, `faqs`, `status`, `order_index`, `created_at`, `updated_at`) VALUES (1, 'industrial-solar-thermal-process-heat', 'Industrial Solar Thermal & Process Heat', 'Parabolic trough and evacuated tube solar collectors generating hot water and pressurized steam up to 180°C for industrial boilers and washing lines.', '["SOLAR THERMAL","INDUSTRIAL PROCESS HEAT"]', 'https://images.unsplash.com/photo-1486406146926-c627a92ad1ab?w=1200&auto=format&fit=crop&q=80', '[{"id":"card-1","image":"https://images.unsplash.com/photo-1486406146926-c627a92ad1ab?w=800&auto=format&fit=crop&q=80","title":"High-Temperature Concentrating Solar Collectors","phase_tag":"PHASE 01 THERMAL CONCENTRATION","image_left":false,"description":"Displacing fossil fuels in industrial boilers, textile dyeing, food processing, and chemical production.","bullet_points":["Delivers pressurized hot water and industrial steam up to 180°C with thermal efficiency exceeding 70%.","Reduces furnace oil, natural gas, and biomass boiler fuel expenses by 30% to 50% annually."]}]', '{"title":"Solar Boiler Feed System","card_color":"#0F172A","button_text":"EXPLORE PROCESS HEAT","description":"Evacuated heat pipes, insulated thermal storage tanks, and high-temperature heat exchangers.","button_color":"#10B981"}', '{"title":"Boiler Fuel Audit","card_color":"#047857","button_text":"SCHEDULE THERMAL AUDIT","description":"Our thermal engineers analyze your steam consumption to engineer a hybrid solar thermal feed system.","button_color":"#F59E0B"}', '[{"answer":"Our industrial concentrating collectors deliver pressurized steam up to 180°C (10 bar), perfectly matching textile dyeing and manufacturing boiler requirements.","question":"What temperature steam can solar thermal systems generate?"}]', 'published', 1, '2026-09-12 18:46:51', '2026-09-12 18:46:51');

